(7297940, 1138028, 177553, '<td valign="top">Awesomely cute!  Well done</td>', 'Awesomely cute!  Well done', '2015-01-02 11:54:25.000000', NULL, 1),
(7297941, 1137879, 177553, '<td valign="top">Great imagination on this, I like the shot and the idea, the only thing I would change is capturing more of the idea of "play".  Maybe a small hand pushing the tank?  Well done.</td>', 'Great imagination on this, I like the shot and the idea, the only thing I would change is capturing more of the idea of "play".  Maybe a small hand pushing the tank?  Well done.', '2015-01-02 11:55:48.000000', NULL, 1),
(7297942, 1138058, 177553, '<td valign="top">Good capture with a good idea. Sort of like game within a game ( playful inception? ).  Maybe adding a hand in the shot to push the idea of "play" more.  Well done.</td>', 'Good capture with a good idea. Sort of like game within a game ( playful inception? ).  Maybe adding a hand in the shot to push the idea of "play" more.  Well done.', '2015-01-02 11:57:07.000000', NULL, 1),
(7297943, 1137792, 177553, '<td valign="top">Well done, well captured.  They look so natural and it doesn''t look staged.  I like that about this shot.  The BW works well here.</td>', 'Well done, well captured.  They look so natural and it doesn''t look staged.  I like that about this shot.  The BW works well here.', '2015-01-02 11:57:50.000000', NULL, 1),
(7297944, 1138124, 177553, '<td valign="top">This conveys the idea of the challenge well and my only complaint would be the distraction of the reflection in the tunnel.</td>', 'This conveys the idea of the challenge well and my only complaint would be the distraction of the reflection in the tunnel.', '2015-01-02 11:58:31.000000', NULL, 1),
(7297946, 1138134, 177553, '<td valign="top">Lol, had to laugh with this one.  Nice capture.  Fabric on the left side seems out of focus, don''t know if this was intentional, but with the short DOF I would have tried to keep it all in focus.  Well done.</td>', 'Lol, had to laugh with this one.  Nice capture.  Fabric on the left side seems out of focus, don''t know if this was intentional, but with the short DOF I would have tried to keep it all in focus.  Well done.', '2015-01-02 12:06:43.000000', NULL, 1),
(7297947, 1138065, 177553, '<td valign="top">Cute idea. Curious if you had an outtake with more DOF in it?  Would be curious to see how the shot looks with more focus throughout.  Good job and good idea.</td>', 'Cute idea. Curious if you had an outtake with more DOF in it?  Would be curious to see how the shot looks with more focus throughout.  Good job and good idea.', '2015-01-02 12:07:58.000000', NULL, 1),
(7297948, 1138054, 177553, '<td valign="top">Walk down memory lane.  The BW works really well here.  Good job.  A little out of focus all the way around, but maybe that was intentional?</td>', 'Walk down memory lane.  The BW works really well here.  Good job.  A little out of focus all the way around, but maybe that was intentional?', '2015-01-02 12:08:38.000000', NULL, 1),
(7297950, 1138089, 177553, '<td valign="top">Beautiful shot.  Nice capture.  It fits the challenge well.</td>', 'Beautiful shot.  Nice capture.  It fits the challenge well.', '2015-01-02 12:09:30.000000', NULL, 1),
(7297951, 1138110, 177553, '<td valign="top">I like this shot, although there is a lot of distraction around the subject which pulls my eye away.  Good job.</td>', 'I like this shot, although there is a lot of distraction around the subject which pulls my eye away.  Good job.', '2015-01-02 12:10:28.000000', NULL, 1),
(7297952, 1138136, 177553, '<td valign="top">Good job. Brings back memories of one of my best friends.  :)</td>', 'Good job. Brings back memories of one of my best friends.  :)', '2015-01-02 12:11:01.000000', NULL, 1),
(7297953, 1137836, 177553, '<td valign="top">Good job, I like the idea here.  Only thing I would be interested in changing is possibly the DOF and getting the front hand in focus as well.</td>', 'Good job, I like the idea here.  Only thing I would be interested in changing is possibly the DOF and getting the front hand in focus as well.', '2015-01-02 12:11:51.000000', NULL, 1),
(7297954, 1138062, 177553, '<td valign="top">Captures the idea of the challenge well.  Seems a little blurred all the way around so I don''t have the in focus "pop" to draw my attention.  Well done.</td>', 'Captures the idea of the challenge well.  Seems a little blurred all the way around so I don''t have the in focus "pop" to draw my attention.  Well done.', '2015-01-02 12:13:35.000000', NULL, 1),
(7297955, 1137751, 177553, '<td valign="top">Nice shot and well captured.  I like the BW on this shot.</td>', 'Nice shot and well captured.  I like the BW on this shot.', '2015-01-02 12:14:11.000000', NULL, 1),
(7297956, 1137713, 177553, '<td valign="top">Well done, although this looks more like "after play".</td>', 'Well done, although this looks more like "after play".', '2015-01-02 12:14:48.000000', NULL, 1),
(7297957, 1137903, 177553, '<td valign="top">Cute shot.</td>', 'Cute shot.', '2015-01-02 12:15:04.000000', NULL, 1),
