(7298002, 1138122, 177553, '<td valign="top">Interesting capture.  I like it. Would you be willing to share the post processing on it?</td>', 'Interesting capture.  I like it. Would you be willing to share the post processing on it?', '2015-01-02 13:51:04.000000', NULL, 1),
(7298004, 1137939, 177553, '<td valign="top">Not a bad shot, and very colorful. What I might change is a capture of the face so its easier to relate to having fun...</td>', 'Not a bad shot, and very colorful. What I might change is a capture of the face so its easier to relate to having fun...', '2015-01-02 13:51:48.000000', NULL, 1),
(7298005, 1137904, 177553, '<td valign="top">I''ve always wanted to try this.  It looks fun.  But without the title it doesn''t convey the idea of "play" to me.  Nice capture.</td>', 'I''ve always wanted to try this.  It looks fun.  But without the title it doesn''t convey the idea of "play" to me.  Nice capture.', '2015-01-02 13:52:43.000000', NULL, 1),
(7298006, 1138085, 177553, '<td valign="top">I like the idea and the BW works well here for me.  But maybe a face in the shot would work better and it might convey the idea of the challenge better as well.</td>', 'I like the idea and the BW works well here for me.  But maybe a face in the shot would work better and it might convey the idea of the challenge better as well.', '2015-01-02 13:54:26.000000', NULL, 1),
