(7298009, 1137779, 177553, '<td valign="top">Not sure what he is doing.  I like the BW here, works well, and the hint of a possible smile helps me connect with the shot from this angle.</td>', 'Not sure what he is doing.  I like the BW here, works well, and the hint of a possible smile helps me connect with the shot from this angle.', '2015-01-02 13:57:18.000000', NULL, 1),
(7298011, 1138037, 177553, '<td valign="top">Cool idea, but the shot strikes me as busy and I have to search for the action.  Maybe another angle would have worked better?  Just my opinion.</td>', 'Cool idea, but the shot strikes me as busy and I have to search for the action.  Maybe another angle would have worked better?  Just my opinion.', '2015-01-02 13:58:35.000000', NULL, 1),
