(7299749, 1137836, 12611, '<td valign="top">Nice mixed focus.</td>', 'Nice mixed focus.', '2015-01-07 09:19:15.000000', NULL, 0),
(7299750, 1138111, 12611, '<td valign="top">Great color and great stark trees to contrast the playfullness. It is not easy to achieve the phenomenon where the human element and nature are at odds to fins the balance, and you did. An all around well put together shot.</td>', 'Great color and great stark trees to contrast the playfullness. It is not easy to achieve the phenomenon where the human element and nature are at odds to fins the balance, and you did. An all around well put together shot.', '2015-01-07 09:21:05.000000', NULL, 0),
(7299751, 1137909, 12611, '<td valign="top">Beautiful light and shimmer, frozen action, and the foreground makes it all linger classically.</td>', 'Beautiful light and shimmer, frozen action, and the foreground makes it all linger classically.', '2015-01-07 09:22:29.000000', NULL, 0),
(7299752, 1138106, 12611, '<td valign="top">Great tones.</td>', 'Great tones.', '2015-01-07 09:22:54.000000', NULL, 0),
